export type MemoryArtifact = {
  key: string;
  value?: string;
  tokenCount?: number;
  type: 'update' | 'delete' | 'error';
  /** Agent partition the write targeted; absent = shared personal pool */
  agentId?: string;
};

export type UIResource = {
  resourceId: string;
  uri: string;
  mimeType?: string;
  text?: string;
  [key: string]: unknown;
};

export type WorkspaceChange = {
  profile: 'stateful';
  operation: 'created' | 'updated';
  path: string;
};

export type TAttachmentMetadata = {
  type?: Tools;
  messageId: string;
  toolCallId: string;
  /** Saved-agent owner when provider tool-call ids repeat across handoffs. */
  agentId?: string;
  /** Host run-step owner when one agent repeats a provider tool-call id. */
  stepId?: string;
  workspaceChange?: WorkspaceChange;
  [Tools.memory]?: MemoryArtifact;
  [Tools.ui_resources]?: UIResource[];
  [Tools.web_search]?: SearchResultData;
  [Tools.file_search]?: SearchResultData;
};

export type TAttachment =
  | (TFile & TAttachmentMetadata)
  | (Pick<TFile, 'filename' | 'filepath' | 'conversationId'> & {
      expiresAt: number;
    } & TAttachmentMetadata)
  | (Partial<Pick<TFile, 'filename' | 'filepath'>> &
      Pick<TFile, 'conversationId'> &
      TAttachmentMetadata);

export type TMessage = z.input<typeof tMessageSchema> & {
  children?: TMessage[];
  content?: TMessageContentParts[];
  files?: Partial<TFile>[];
  depth?: number;
  siblingIndex?: number;
  attachments?: TAttachment[];
  clientTimestamp?: string;
  /** Client-only durable branch anchor while this message is an optimistic response. */
  clientQueueParentMessageId?: string;
  feedback?: TFeedback;
};

export type ContentPart = (
  | CodeToolCall
  | RetrievalToolCall
  | FileSearchToolCall
  | FunctionToolCall
  | Agents.AgentToolCall
  | ImageFile
  | Text
) &
  PartMetadata;

export type TextData = (Text & PartMetadata) | undefined;

export type SummaryContentPart = {
  type: ContentTypes.SUMMARY;
  content?: Array<{ type: ContentTypes.TEXT; text: string }>;
  tokenCount?: number;
  summarizing?: boolean;
  /** A summarize round that ended in error. Partial deltas already streamed
   *  into this slot are kept, so the renderer needs this to avoid presenting
   *  truncated text under the "Conversation summarized" label. */
  failed?: boolean;
  /** Set when the user compacted the context manually rather than the
   *  automatic detour firing on context pressure. */
  initiatedBy?: 'user';
  summaryVersion?: number;
  model?: string;
  provider?: string;
  createdAt?: string;
  boundary?: {
    messageId: string;
    contentIndex: number;
  };
};

/**
 * A user steering message injected mid-run at a tool-batch boundary.
 * Persisted inline in the response message's content array (keyed by the
 * type name like `text`/`think` so token counting reads it for free);
 * replayed as a user message on subsequent turns by `formatAgentMessages`.
 */
export type SteerContentPart = {
  type: ContentTypes.STEER;
  steer: string;
  steerId?: string;
  /** Stable optimistic-client id used to settle a POST whose response was lost. */
  clientSteerId?: string;
  createdAt?: number;
  /** Attachments steered with the message; re-encoded per turn on replay
   *  like any other user-message media (refs only, never encoded data). */
  files?: Partial<TFile>[];
  /** Quoted excerpts steered with the message, persisted separately from the
   *  typed text (mirroring `TMessage.quotes`) so the UI renders them as
   *  reference blocks; merged into the model-bound user turn on every replay. */
  quotes?: string[];
};

export type TMessageContentParts =
  | ({
      type: ContentTypes.ERROR;
      text?: string | TextData;
      error?: string;
      /** Set when this failure is what a manual compaction produced instead of a
       *  summary. The turn has no other record of having been one, so the rerun
       *  controls read it the same way they read a summary's marker. */
      initiatedBy?: 'user';
    } & ContentMetadata)
  | ({
      type: ContentTypes.THINK;
      think?: string | TextData;
      /** Generated orientation for this user-visible reasoning step. */
      reasoning_label?: string;
      /** Stable SDK run-step identity used to correlate live revisions. */
      reasoning_label_step_id?: string;
      /** Durable provider-call count used to enforce the per-run cost cap across resumes. */
      reasoning_label_attempts?: number;
      /** Visible reasoning length included in this step's latest provider call. */
      reasoning_label_submitted_chars?: number;
      /** Monotonic provider-call revision; gaps are allowed after unsuccessful attempts. */
      reasoning_label_revision?: number;
      /** Whether the reasoning step can still produce a newer label. */
      reasoning_label_status?: 'streaming' | 'complete';
      /** The reasoning happened but its text is not available to this view
       *  (e.g. detached subagent projections retain only a marker). */
      reasoning_unavailable?: boolean;
    } & ContentMetadata)
  | (SteerContentPart & ContentMetadata)
  | ({
      type: ContentTypes.TEXT;
      text?: string | TextData;
      tool_call_ids?: string[];
      /** Open Responses semantic channel for assistant text. */
      phase?: 'commentary' | 'final_answer';
    } & ContentMetadata)
  | ({
      type: ContentTypes.TOOL_CALL;
      tool_call: (
        | CodeToolCall
        | RetrievalToolCall
        | FileSearchToolCall
        | FunctionToolCall
        | Agents.AgentToolCall
      ) &
        PartMetadata;
    } & ContentMetadata)
  | ({ type: ContentTypes.IMAGE_FILE; image_file: ImageFile & PartMetadata } & ContentMetadata)
  | (SummaryContentPart & ContentMetadata)
  | ({
      /** One-line LLM-generated note describing a completed tool batch. UI-only:
       *  never sent to the model (stripped before payload formatting). */
      type: ContentTypes.ACTIVITY_LABEL;
      activity_label?: string;
      /** Missing means the legacy/per-batch activity label. */
      activity_label_type?: 'phase';
      tool_call_ids?: string[];
      /** Parent phase bounds and telemetry. */
      activity_start_index?: number;
      /** Exclusive end of the grouped content; may precede the marker itself. */
      activity_end_index?: number;
      activity_count?: number;
      agent_ids?: string[];
      /** ok = all tools succeeded, failed = all failed, partial = mixed. */
      status?: 'ok' | 'partial' | 'failed';
      pending?: boolean;
    } & ContentMetadata)
  | (Agents.AgentUpdate & ContentMetadata)
  | (Agents.MessageContentImageUrl & ContentMetadata)
  | (Agents.MessageContentVideoUrl & ContentMetadata)
  | (Agents.MessageContentInputAudio & ContentMetadata);

/** The immutable origin of a file explicitly published from an agent execution. */
export type RunFileProvenance = {
  runId: string;
  executionId: string;
  agentId: string;
  parentExecutionId?: string;
  parentAgentId?: string;
  recipientAgentIds?: string[];
  sourceFileId: string;
  publishedAt: string;
  inputFileIds: string[];
};

export type TFile = {
  _id?: string;
  __v?: number;
  user: string;
  tenantId?: string;
  storageRegion?: string;
  storageKey?: string;
  conversationId?: string;
  message?: string;
  file_id: string;
  temp_file_id?: string;
  bytes: number;
  embedded: boolean;
  filename: string;
  filepath: string;
  object: 'file';
  type: string;
  usage: number;
  context?: FileContext;
  source?: FileSources;
  filterSource?: FileSources;
  width?: number;
  height?: number;
  expiresAt?: string | Date;
  preview?: string;
  text?: string;
  /**
   * Format of the `text` field. `'html'` means the backend produced
   * a sanitized full-document HTML preview the client may inject as
   * `index.html` inside the office artifact iframe. `'text'` (or
   * `undefined` for legacy records) is plain text and MUST NOT be
   * injected as HTML — render through the markdown/escaping path.
   * See Codex P1 review on PR #12934.
   */
  textFormat?: 'html' | 'text' | null;
  /**
   * Lifecycle of the inline preview rendered from `text`. `'pending'`
   * while background HTML extraction is in flight (deferred-preview
   * code-execution flow), `'ready'` once `text`/`textFormat` are set,
   * `'failed'` if extraction errored or hit the 60s ceiling. `undefined`
   * for legacy records and for files that never expect a preview —
   * clients MUST treat that as `'ready'`.
   */
  status?: 'pending' | 'ready' | 'failed';
  /**
   * Short machine-readable failure reason when `status === 'failed'`.
   * Suitable for tooltip text but not user-facing prose.
   */
  previewError?: string;
  metadata?: {
    runFile?: RunFileProvenance;
    fileIdentifier?: string;
    /**
     * Structured form of `fileIdentifier`. Persisted alongside the
     * legacy string during the dual-write transition; readers should
     * resolve via `resolveCodeEnvRef`.
     */
    codeEnvRef?: CodeEnvRef;
    codeEnvRefs?: CodeEnvRefMap;
    /** Dispatch-order stamp for the current source artifact generation. */
    sourceDispatchedAt?: number;
    /** Vector namespaces this file has been embedded into. */
    embeddedEntities?: string[];
    /** The user named this destination, so absent ones were declined. */
    destinationChosen?: boolean;
    /** The type the delivery route was resolved against, when conversion changed it. */
    routingMimeType?: string;
  };
  llmDeliveryPath?: 'provider' | 'text' | 'none';
  createdAt?: string | Date;
  updatedAt?: string | Date;
};

export type TFileUpload = TFile & {
  temp_file_id: string;

